const router = express.Router();
router.get('/:id', (req, res) => res.send('found'));
const app = express().use('/books', router);
const server = app.listen(0, async () => {
  const url = `http://localhost:${server.address().port}`;
  const a = await fetch(`${url}/books/7`);
  const b = await fetch(`${url}/7`);
  console.log(a.status, b.status);
  server.close();
});
